    /**
     * Tests getting all InsuredObjects.
     *
     * @return    Collection
     */
    public List<InsuredObject> testGetAll() throws Throwable {
    LOGGER.info( "InsuredObjectTest:testGetAll() - Retrieving Collection of InsuredObjects:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all InsuredObject : " );
    List<InsuredObject> collection  = null;

    try {
        // call the static get method on the InsuredObjectService
        collection = service.getAllInsuredObject();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            InsuredObject currEntity  = null;
            Iterator<InsuredObject> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInsuredObjectId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

